class Solution {
    public int maxAreaOfIsland(int[][] grid) {
        int best = 0;
        for (int row = 0; row < grid.length; row++) {
            for (int col = 0; col < grid[0].length; col++) {
                if (grid[row][col] == 1) {
                    best = Math.max(best, area(grid, row, col));
                }
            }
        }
        return best;
    }

    private int area(int[][] grid, int row, int col) {
        if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || grid[row][col] != 1) {
            return 0;
        }

        grid[row][col] = 0;
        return 1
                + area(grid, row + 1, col)
                + area(grid, row - 1, col)
                + area(grid, row, col + 1)
                + area(grid, row, col - 1);
    }
}

import java.util.*;

class Solution {
    public int maxAreaOfIsland(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int best = 0;
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (grid[row][col] != 1) {
                    continue;
                }

                int area = 0;
                Queue<int[]> queue = new ArrayDeque<>();
                grid[row][col] = 0;
                queue.offer(new int[]{row, col});

                while (!queue.isEmpty()) {
                    int[] cell = queue.poll();
                    area++;
                    for (int[] direction : directions) {
                        int nextRow = cell[0] + direction[0];
                        int nextCol = cell[1] + direction[1];
                        if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) {
                            continue;
                        }
                        if (grid[nextRow][nextCol] != 1) {
                            continue;
                        }
                        grid[nextRow][nextCol] = 0;
                        queue.offer(new int[]{nextRow, nextCol});
                    }
                }
                best = Math.max(best, area);
            }
        }
        return best;
    }
}

import java.util.*;

class Solution {
    private int[] parent;
    private int[] size;

    public int maxAreaOfIsland(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        parent = new int[rows * cols];
        size = new int[rows * cols];
        Arrays.fill(parent, -1);
        int best = 0;

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (grid[row][col] == 1) {
                    int id = row * cols + col;
                    parent[id] = id;
                    size[id] = 1;
                    best = 1;
                }
            }
        }

        int[][] directions = {{1, 0}, {0, 1}};
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (grid[row][col] != 1) {
                    continue;
                }
                int id = row * cols + col;
                for (int[] direction : directions) {
                    int nextRow = row + direction[0];
                    int nextCol = col + direction[1];
                    if (nextRow < rows && nextCol < cols && grid[nextRow][nextCol] == 1) {
                        best = Math.max(best, union(id, nextRow * cols + nextCol));
                    }
                }
            }
        }
        return best;
    }

    private int find(int node) {
        if (parent[node] != node) {
            parent[node] = find(parent[node]);
        }
        return parent[node];
    }

    private int union(int first, int second) {
        int rootFirst = find(first);
        int rootSecond = find(second);
        if (rootFirst == rootSecond) {
            return size[rootFirst];
        }
        if (size[rootFirst] < size[rootSecond]) {
            int temp = rootFirst;
            rootFirst = rootSecond;
            rootSecond = temp;
        }
        parent[rootSecond] = rootFirst;
        size[rootFirst] += size[rootSecond];
        return size[rootFirst];
    }
}

import java.util.*;

class Solution {
    public int maxAreaOfIsland(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] labels = new int[rows][cols];
        int[] parent = new int[rows * cols + 1];
        int[] rank = new int[rows * cols + 1];
        int nextLabel = 1;

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (grid[row][col] == 0) {
                    continue;
                }

                int up = row > 0 ? labels[row - 1][col] : 0;
                int left = col > 0 ? labels[row][col - 1] : 0;
                if (up == 0 && left == 0) {
                    labels[row][col] = nextLabel;
                    parent[nextLabel] = nextLabel;
                    nextLabel++;
                } else if (up == 0 || left == 0) {
                    labels[row][col] = up == 0 ? left : up;
                } else {
                    labels[row][col] = Math.min(up, left);
                    union(parent, rank, up, left);
                }
            }
        }

        Map<Integer, Integer> areaByRoot = new HashMap<>();
        int best = 0;
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (labels[row][col] == 0) {
                    continue;
                }
                int root = find(parent, labels[row][col]);
                int area = areaByRoot.getOrDefault(root, 0) + 1;
                areaByRoot.put(root, area);
                best = Math.max(best, area);
            }
        }
        return best;
    }

    private int find(int[] parent, int label) {
        if (parent[label] != label) {
            parent[label] = find(parent, parent[label]);
        }
        return parent[label];
    }

    private void union(int[] parent, int[] rank, int first, int second) {
        int rootFirst = find(parent, first);
        int rootSecond = find(parent, second);
        if (rootFirst == rootSecond) {
            return;
        }
        if (rank[rootFirst] < rank[rootSecond]) {
            parent[rootFirst] = rootSecond;
        } else if (rank[rootFirst] > rank[rootSecond]) {
            parent[rootSecond] = rootFirst;
        } else {
            parent[rootSecond] = rootFirst;
            rank[rootFirst]++;
        }
    }
}
